package app.nlc.moveqa;
import android.app.Instrumentation;import android.os.Bundle;import android.content.Context;import android.net.Uri;import android.provider.DocumentsContract;import android.database.sqlite.SQLiteDatabase;import org.json.*;import java.io.*;import java.lang.reflect.*;import java.util.*;import java.security.MessageDigest;
public class LocalMoveQA extends Instrumentation {
 Bundle args;Context ctx;Object nativeMove;Class<?> cls,callbackClass;File work;String qaRoot;List<String> jobs=new ArrayList<>();JSONArray passed=new JSONArray();
 public void onCreate(Bundle b){super.onCreate(b);args=b;start();}
 Object call(String name,Object...v)throws Exception{for(Method m:cls.getMethods())if(m.getName().equals(name)&&m.getParameterCount()==v.length)try{return m.invoke(nativeMove,v);}catch(InvocationTargetException e){throw (Exception)e.getCause();}throw new Exception("Missing "+name);}
 Object progress(boolean cancel,String id)throws Exception{return Proxy.newProxyInstance(callbackClass.getClassLoader(),new Class<?>[]{callbackClass},(p,m,v)->{if(m.getName().equals("invoke")&&cancel&&"copy".equals(v[0])&&((Number)v[1]).longValue()>2*1024*1024)call("cancel",id);return Class.forName("kotlin.Unit",true,ctx.getClassLoader()).getField("INSTANCE").get(null);});}
 void ok(boolean b,String s)throws Exception{if(!b)throw new Exception(s);}
 String uri(File f){return Uri.fromFile(f).toString();}
 String file(String name,String text)throws Exception{File f=new File(work,name);try(OutputStream out=new FileOutputStream(f)){out.write(text.getBytes("UTF-8"));}return uri(f);}
 Uri document(String raw){Uri u=Uri.parse(raw);return u.getScheme().equals("content")&&!u.getPath().contains("/document/")?DocumentsContract.buildDocumentUriUsingTree(u,DocumentsContract.getTreeDocumentId(u)):u;}
 String create(String parent,String name,boolean folder)throws Exception{Uri u=document(parent);if(u.getScheme().equals("file")){File f=new File(u.getPath(),name);if(folder)ok(f.mkdir(),"mkdir");else ok(f.createNewFile(),"create");return uri(f);}return DocumentsContract.createDocument(ctx.getContentResolver(),u,folder?DocumentsContract.Document.MIME_TYPE_DIR:"application/octet-stream",name).toString();}
 void write(String uri,String text)throws Exception{try(OutputStream out=ctx.getContentResolver().openOutputStream(Uri.parse(uri),"wt")){out.write(text.getBytes("UTF-8"));}}
 String read(String uri)throws Exception{try(InputStream in=ctx.getContentResolver().openInputStream(Uri.parse(uri))){ByteArrayOutputStream out=new ByteArrayOutputStream();byte[]b=new byte[4096];int n;while((n=in.read(b))>=0)out.write(b,0,n);return out.toString("UTF-8");}}
 String sha(String uri)throws Exception{MessageDigest d=MessageDigest.getInstance("SHA-256");try(InputStream in=ctx.getContentResolver().openInputStream(Uri.parse(uri))){byte[]b=new byte[128*1024];int n;while((n=in.read(b))>=0)d.update(b,0,n);}StringBuilder s=new StringBuilder();for(byte b:d.digest())s.append(String.format("%02x",b&255));return s.toString();}
 List<String> list(String raw)throws Exception{List<String> out=new ArrayList<>();Uri u=document(raw);if(u.getScheme().equals("file")){File[]files=new File(u.getPath()).listFiles();if(files!=null)for(File f:files)out.add(uri(f));}else{Uri children=DocumentsContract.buildChildDocumentsUriUsingTree(u,DocumentsContract.getDocumentId(u));try(android.database.Cursor c=ctx.getContentResolver().query(children,new String[]{DocumentsContract.Document.COLUMN_DOCUMENT_ID},null,null,null)){while(c.moveToNext())out.add(DocumentsContract.buildDocumentUriUsingTree(u,c.getString(0)).toString());}}return out;}
 String[] services={"music","podcast","video","focus","wealth","health"};
 JSONObject targets;
 JSONObject plan(String source)throws Exception{return new JSONObject().put("metadata",new JSONObject().put("fingerprint","native-qa")).put("general",qaRoot).put("targets",targets).put("sources",new JSONArray().put(new JSONObject().put("service","music").put("uri",source))).put("extras",new JSONArray());}
 String newJob(){String id=UUID.randomUUID().toString();jobs.add(id);return id;}
 JSONObject prepare(String id,JSONObject plan)throws Exception{return new JSONObject((String)call("prepare",ctx,id,file("plan.json",plan.toString()),progress(false,id)));}
 JSONArray copy(String id,boolean cancel)throws Exception{return new JSONObject(read((String)call("copy",ctx,id,progress(cancel,id)))).getJSONArray("files");}
 void receipt(String id,String nonce)throws Exception{File f=new File(ctx.getFilesDir(),"SQLite/nlc-catalog.db");f.getParentFile().mkdirs();try(SQLiteDatabase d=SQLiteDatabase.openOrCreateDatabase(f,null)){d.execSQL("CREATE TABLE IF NOT EXISTS meta (key TEXT PRIMARY KEY,value TEXT NOT NULL)");d.execSQL("INSERT OR REPLACE INTO meta VALUES (?,?)",new Object[]{"local_move_receipt:"+id,nonce});}}
 String mirrors()throws Exception{return file("mirrors.json",new JSONObject().put("music","{\"version\":1,\"updatedAt\":1,\"playlists\":[]}").put("focus","{\"version\":1,\"projects\":[],\"tasks\":[],\"reminders\":[],\"updatedAt\":1}").put("wealth","{\"version\":1,\"accounts\":[],\"assets\":[],\"txs\":[],\"updatedAt\":1}").toString());}
 JSONObject finish(String id)throws Exception{return new JSONObject((String)call("finish",ctx,id,mirrors(),progress(false,id)));}
 void rejected(String expected,Run action)throws Exception{boolean rejected=false;try{action.run();}catch(Exception e){rejected=e.getMessage().contains(expected);}ok(rejected,"Expected "+expected);}
 interface Run{void run()throws Exception;}
 public void onStart(){Bundle result=new Bundle();int code=0;try{
 ctx=getTargetContext();cls=Class.forName("app.nlc.lanbridge.LocalMove",true,ctx.getClassLoader());nativeMove=cls.getField("INSTANCE").get(null);callbackClass=Class.forName("kotlin.jvm.functions.Function3",true,ctx.getClassLoader());work=new File(ctx.getCacheDir(),"move-native-qa-"+UUID.randomUUID());ok(work.mkdir(),"work");
 String parent=null;if(!Boolean.parseBoolean(args.getString("private","false")))for(android.content.UriPermission p:ctx.getContentResolver().getPersistedUriPermissions())if(Uri.decode(p.getUri().toString()).contains("NLC-General-QA")){parent=p.getUri().toString();break;}
 if(parent==null){ok(Boolean.parseBoolean(args.getString("private","false")),"Grant NLC-General-QA in onboarding first, or pass --private");parent=uri(work);}qaRoot=create(parent,"Move-QA-"+UUID.randomUUID(),true);targets=new JSONObject();for(String s:services)targets.put(s,new JSONObject().put("uri",create(qaRoot,s,true)));
 File source=new File(work,"source");ok(source.mkdir(),"source");File large=new File(source,"large.bin");long size=Long.parseLong(args.getString("size","335544320"));byte[]block=new byte[128*1024];new Random(995).nextBytes(block);try(OutputStream out=new BufferedOutputStream(new FileOutputStream(large))){for(long n=0;n<size;n+=block.length)out.write(block);}String expected=sha(uri(large));
 String preexisting=create(targets.getJSONObject("music").getString("uri"),"large.bin",false);write(preexisting,"existing destination");
 String oldPlaylists=create(targets.getJSONObject("music").getString("uri"),"nlc-playlists.json",false);write(oldPlaylists,"prior playlist snapshot");
 String oldMirror=create(targets.getJSONObject("focus").getString("uri"),"nlc-tasks.json",false);write(oldMirror,"prior task snapshot");
 final String id=newJob();JSONObject job=prepare(id,plan(uri(source)));ok(job.getLong("bytes")==size,"large inventory");
 rejected("cancelled",()->copy(id,true));ok(large.exists()&&sha(uri(large)).equals(expected),"cancel preserved original");passed.put("cancel-stream-preserves-original");
 prepare(id,plan(uri(source)));JSONArray files=copy(id,false);JSONObject moved=files.getJSONObject(0);ok(sha(moved.getString("uri")).equals(expected),"large SHA");ok(!moved.getString("uri").equals(preexisting)&&read(preexisting).equals("existing destination"),"name collision");passed.put("collision-keeps-both-with-actual-path");
 call("verify",ctx,id,progress(false,id));rejected("notCommitted",()->finish(id));ok(large.exists(),"no cleanup without SQL receipt");passed.put("cleanup-requires-actual-committed-sql-receipt");
 for(String marker:list(targets.getJSONObject("music").getString("uri")))if(Uri.decode(marker).endsWith(".nlc-moving-"+id))write(marker,"edited marker data");
 receipt(id,job.getString("nonce"));JSONArray pending=new JSONArray((String)call("pending",ctx));boolean recovered=false;for(int i=0;i<pending.length();i++)if(pending.getJSONObject(i).getString("id").equals(id))recovered=pending.getJSONObject(i).getString("state").equals("committed");ok(recovered,"resume committed job");passed.put("recovery-detects-sql-commit-before-cleanup");
 JSONObject finished=finish(id);ok(finished.getString("state").equals("done")&&!large.exists(),"verified cleanup");ok(sha(moved.getString("uri")).equals(expected)&&read(preexisting).equals("existing destination"),"destination safe");passed.put("large-stream-move-sha256");
 boolean hidden=false;for(String u:list(targets.getJSONObject("music").getString("uri")))if(Uri.decode(u).endsWith(".partial"))hidden=true;ok(hidden,"resumed partial must not be exposed as playable media");passed.put("interrupted-copy-retained-as-non-media");
 boolean markerKept=false;for(String u:list(targets.getJSONObject("music").getString("uri")))if(Uri.decode(u).contains(".nlc-retained-marker-")&&read(u).equals("edited marker data"))markerKept=true;ok(markerKept,"edited marker must not be deleted");passed.put("edited-marker-preserved-as-non-media");
 boolean snapshot=false;for(String u:list(targets.getJSONObject("focus").getString("uri")))if(read(u).equals("prior task snapshot"))snapshot=true;ok(snapshot,"pre-existing tasks snapshot must survive mirror rotation");passed.put("mirror-rotation-preserves-existing-destination");
 boolean oldLists=false;for(String u:list(targets.getJSONObject("music").getString("uri")))if(Uri.decode(u).contains("nlc-playlists.before-")&&read(u).equals("prior playlist snapshot"))oldLists=true;ok(oldLists,"pre-existing playlist snapshot must survive mirror rotation");passed.put("playlist-mirror-keeps-prior-snapshot");
 String noop=newJob();JSONObject same=prepare(noop,plan(targets.getJSONObject("music").getString("uri")));ok(same.getInt("files")==0,"same target must not copy files");copy(noop,false);receipt(noop,same.getString("nonce"));finish(noop);ok(sha(moved.getString("uri")).equals(expected),"same-target move preserves destination");passed.put("same-folder-is-noop-with-canonical-uris");
 // A shared file already under one destination must stay there for that service.
 String shared=create(targets.getJSONObject("music").getString("uri"),"shared.txt",false);write(shared,"shared source");String sharedId=newJob();JSONObject sharedPlan=plan(uri(work)).put("sources",new JSONArray()).put("extras",new JSONArray().put(new JSONObject().put("service","music").put("ref","track:music").put("uri",shared).put("path","shared.txt")).put(new JSONObject().put("service","podcast").put("ref","track:podcast").put("uri",shared).put("path","shared.txt")));JSONObject sharedJob=prepare(sharedId,sharedPlan);copy(sharedId,false);receipt(sharedId,sharedJob.getString("nonce"));finish(sharedId);ok(read(shared).equals("shared source"),"shared in-place source retained");passed.put("shared-source-keeps-live-in-place-reference");
 // An edited source survives cleanup after references have been committed.
 File small=new File(work,"small");ok(small.mkdir(),"small");File original=new File(small,"edited.txt");try(OutputStream out=new FileOutputStream(original)){out.write("before".getBytes());}
 String changed=newJob();JSONObject cp=prepare(changed,plan(uri(small)));copy(changed,false);call("verify",ctx,changed,progress(false,changed));try(OutputStream out=new FileOutputStream(original)){out.write("after".getBytes());}receipt(changed,cp.getString("nonce"));JSONObject retained=finish(changed);ok(original.exists()&&retained.getInt("retained")==1,"edited original kept");call("keepOriginals",ctx,changed);passed.put("changed-original-retained-after-commit");
 String unreadable=newJob();JSONObject up=prepare(unreadable,plan(uri(small)));copy(unreadable,false);call("verify",ctx,unreadable,progress(false,unreadable));receipt(unreadable,up.getString("nonce"));ok(original.setReadable(false,false),"chmod source unreadable");try{JSONObject unread=finish(unreadable);ok(original.exists()&&unread.getInt("retained")==1,"unreadable source preserved");}finally{original.setReadable(true,true);}call("keepOriginals",ctx,unreadable);passed.put("unreadable-original-retained");
 // Corrupted destination never authorizes deletion and is retained on abort.
 String corrupt=newJob();prepare(corrupt,plan(uri(small)));JSONArray copied=copy(corrupt,false);write(copied.getJSONObject(0).getString("uri"),"corrupted");rejected("integrity",()->call("verify",ctx,corrupt,progress(false,corrupt)));JSONObject aborted=new JSONObject((String)call("abort",ctx,corrupt));ok(original.exists()&&aborted.getInt("kept")==1,"abort preserves edited copy and original");passed.put("corrupt-copy-rejected-and-edited-data-preserved");
 // Destination inside an old source must never scan its own newly created children.
 File nested=new File(work,"nested");ok(nested.mkdir(),"nested source");String nestedFile=create(uri(nested),"original.txt",false);write(nestedFile,"nested original");String nestedRoot=create(uri(nested),"general",true);JSONObject nestedTargets=new JSONObject();for(String service:services)nestedTargets.put(service,new JSONObject().put("uri",create(nestedRoot,service,true)));JSONObject np=plan(uri(nested)).put("general",nestedRoot).put("targets",nestedTargets);String nestedId=newJob();JSONObject nestedPlan=prepare(nestedId,np);ok(nestedPlan.getInt("files")==1,"nested destination excluded from inventory");copy(nestedId,false);call("abort",ctx,nestedId);ok(read(nestedFile).equals("nested original"),"cancel nested keeps original");passed.put("nested-target-excluded-with-safe-abort");
 result.putString("report",new JSONObject().put("passed",passed).put("mediaBytes",size).put("sha256",expected).put("SAF",qaRoot.startsWith("content:")).put("maxJavaHeap",Runtime.getRuntime().maxMemory()).toString());
 }catch(Throwable e){result.putString("error",e.toString());result.putString("passed",passed.toString());code=1;}finally{
 for(String id:jobs)try{File f=new File(ctx.getFilesDir(),"SQLite/nlc-catalog.db");try(SQLiteDatabase d=SQLiteDatabase.openDatabase(f.getPath(),null,SQLiteDatabase.OPEN_READWRITE)){d.execSQL("DELETE FROM meta WHERE key=?",new Object[]{"local_move_receipt:"+id});}delete(new File(ctx.getFilesDir(),"local-moves/"+id));}catch(Exception ignored){}
 if(qaRoot!=null)try{Uri u=Uri.parse(qaRoot);if(u.getScheme().equals("content"))DocumentsContract.deleteDocument(ctx.getContentResolver(),u);else delete(new File(u.getPath()));}catch(Exception ignored){}if(work!=null)delete(work);
 }finish(code,result);}
 void delete(File f){if(f.isDirectory()){File[]c=f.listFiles();if(c!=null)for(File child:c)delete(child);}f.delete();}
}
